const belanjaan: [string, number, number][] = [
  ["Kopi Susu", 18000, 2],
  ["Roti Bakar", 15000, 1],
  ["Air Mineral", 5000, 3],
];
let subtotal = 0;
for (const [nama, harga, jumlah] of belanjaan) {
  subtotal += harga * jumlah;
}
const diskonMember: number | undefined = undefined;
const diskon = diskonMember ?? 0;
console.log("Subtotal:", subtotal);
console.log("Bayar:", subtotal - diskon);

