const belanjaan: [string, number, number][] = [
  ["Gula", 14000, 2],
  ["Teh", 8000, 1],
  ["Susu", 7500, 2],
];
const persenMember: number | undefined = undefined;
let subtotal = 0;
for (const [, harga, jumlah] of belanjaan) {
  subtotal += harga * jumlah;
}
const diskon = Math.round((subtotal * (persenMember ?? 0)) / 100);
console.log("Barang:", belanjaan.length, "jenis");
console.log("Subtotal:", subtotal);
console.log("Bayar:", subtotal - diskon);
